// web/replay.ts
function mountReplay(hooks) {
  let active = false, index, at = 0, playing = false, version = 0, abort, speed = 60, lastReal = 0;
  const clock = new Intl.DateTimeFormat(undefined, { timeZone: "America/Chicago", hour: "2-digit", minute: "2-digit", second: "2-digit" });
  const date = new Intl.DateTimeFormat(undefined, { timeZone: "America/Chicago", dateStyle: "medium" });
  const button = document.createElement("button");
  button.id = "open-recordings";
  button.textContent = "◷ Recordings";
  button.title = "Browse recorded observing nights";
  document.querySelector(".header-right").prepend(button);
  const picker = document.createElement("dialog");
  picker.className = "recordings-dialog";
  picker.setAttribute("aria-label", "Night recordings");
  picker.innerHTML = '<header><div><small>OBSERVATORY ARCHIVE</small><h2>Night recordings</h2></div><button class="close-recordings" aria-label="Close recordings">×</button></header><p class="recordings-status" role="status"></p><div class="recordings-list"></div>';
  document.body.append(picker);
  picker.querySelector(".close-recordings").onclick = () => picker.close();
  const bar = document.createElement("section");
  bar.id = "replay-timeline";
  bar.hidden = true;
  bar.setAttribute("aria-label", "Recording playback");
  bar.innerHTML = '<div class="replay-heading"><strong>REPLAY</strong><span id="replay-night"></span><time id="replay-clock"></time><span id="replay-state" role="status"></span><button id="return-live">Return to Live ↗</button></div><div class="replay-controls"><button id="replay-play" aria-label="Play recording">▶</button><button id="replay-previous" aria-label="Previous event">│◀</button><button id="replay-next" aria-label="Next event">▶│</button><select id="replay-speed" aria-label="Playback speed"><option value="1">1×</option><option value="10">10×</option><option value="60" selected>60×</option><option value="300">300×</option></select><div class="replay-track"><div class="replay-marks" aria-hidden="true"></div><input id="replay-scrubber" aria-label="Recording time" type="range" step="1000"><div class="replay-scale"></div></div><select id="replay-events" aria-label="Jump to recorded event"><option value="">Events</option></select></div>';
  document.body.append(bar);
  const find = (id) => bar.querySelector("#" + id);
  const slider = find("replay-scrubber"), status = find("replay-state"), play = find("replay-play");
  const label = (text) => {
    status.textContent = text;
  };
  function stop() {
    playing = false;
    play.textContent = "▶";
    play.setAttribute("aria-label", "Play recording");
  }
  function leave() {
    ++version;
    abort?.abort();
    stop();
    active = false;
    index = undefined;
    bar.hidden = true;
    document.body.classList.remove("replay-mode");
    hooks.mode(false);
  }
  find("return-live").onclick = leave;
  async function seek(time) {
    if (!active || !index)
      return;
    const ticket = ++version;
    abort?.abort();
    abort = new AbortController;
    at = Math.max(index.start, Math.min(index.end, time));
    slider.value = String(at);
    label("Loading recorded state…");
    try {
      const frame = await hooks.read("/api/v1/recordings/" + index.id + "/state?at=" + Math.round(at), abort.signal);
      if (ticket !== version || !active)
        return;
      hooks.frame(frame);
      find("replay-clock").textContent = clock.format(frame.at) + " Central";
      label(frame.gap ? "No recorded telemetry · last update " + (frame.lastTelemetryAt ? clock.format(frame.lastTelemetryAt) : "unavailable") : "Recorded telemetry · controls disabled");
      status.classList.toggle("gap", frame.gap);
    } catch (error) {
      if (ticket === version && active) {
        stop();
        label(error instanceof Error ? error.message : "Could not load recording");
      }
    }
  }
  function track() {
    if (!index)
      return;
    const duration = Math.max(1, index.end - index.start), marks = bar.querySelector(".replay-marks");
    marks.replaceChildren();
    for (const gap of index.gaps) {
      const span = document.createElement("i");
      span.className = "replay-gap";
      span.style.left = (gap.start - index.start) / duration * 100 + "%";
      span.style.width = (gap.end - gap.start) / duration * 100 + "%";
      marks.append(span);
    }
    const chosen = index.events.filter((e) => e.kind !== "step").concat(index.events.filter((e) => e.kind === "step")).slice(0, 180);
    for (const event of chosen) {
      const mark = document.createElement("i");
      mark.className = "replay-mark kind-" + event.kind;
      mark.style.left = (event.at - index.start) / duration * 100 + "%";
      marks.append(mark);
    }
    const scale = bar.querySelector(".replay-scale");
    scale.replaceChildren();
    for (let i = 0;i <= 4; i++) {
      const t = document.createElement("span");
      t.textContent = clock.format(index.start + duration * i / 4);
      scale.append(t);
    }
    const events = find("replay-events");
    events.replaceChildren(new Option("Events · " + index.events.length, ""));
    for (const e of index.events)
      events.add(new Option(clock.format(e.at) + " · " + e.label, String(e.at)));
  }
  async function select(recording) {
    picker.close();
    stop();
    abort?.abort();
    const ticket = ++version;
    active = true;
    index = undefined;
    document.body.classList.add("replay-mode");
    bar.hidden = false;
    find("replay-night").textContent = date.format(Date.parse(recording.startedAt));
    label("Indexing recording…");
    hooks.mode(true);
    slider.disabled = true;
    play.disabled = true;
    try {
      const result = await hooks.read("/api/v1/recordings/" + recording.id);
      if (!active || ticket !== version)
        return;
      index = result;
      at = index.start;
      slider.min = String(index.start);
      slider.max = String(index.end);
      slider.disabled = false;
      play.disabled = false;
      track();
      await seek(index.firstTelemetryAt || at);
    } catch (e) {
      if (active && ticket === version)
        label(e instanceof Error ? e.message : "Could not open recording");
    }
  }
  button.onclick = async () => {
    const listing = picker.querySelector(".recordings-list"), message = picker.querySelector(".recordings-status");
    listing.replaceChildren();
    message.textContent = "Loading recordings…";
    picker.showModal();
    try {
      const entries = await hooks.read("/api/v1/recordings");
      message.textContent = entries.length ? "Times shown in America/Chicago. Shaded regions mark missing telemetry." : "No recordings yet.";
      for (const r of entries) {
        const row = document.createElement("button");
        row.className = "recording-entry";
        row.disabled = r.state === "recording";
        row.dataset.recordingId = r.id;
        const title = document.createElement("strong");
        title.textContent = date.format(Date.parse(r.startedAt));
        const sub = document.createElement("span");
        sub.textContent = clock.format(Date.parse(r.startedAt)) + " · " + r.rig + (r.environment === "simulation" ? " · Simulation" : "");
        const badge = document.createElement("small");
        badge.textContent = r.state === "recording" ? "Recording now" : r.state;
        row.append(title, sub, badge);
        row.onclick = () => void select(r);
        listing.append(row);
      }
    } catch (e) {
      message.textContent = e instanceof Error ? e.message : "Recording archive unavailable";
    }
  };
  let scrubTimer;
  slider.oninput = () => {
    stop();
    clearTimeout(scrubTimer);
    scrubTimer = setTimeout(() => void seek(Number(slider.value)), 100);
  };
  slider.onchange = () => {
    clearTimeout(scrubTimer);
    seek(Number(slider.value));
  };
  find("replay-events").onchange = (event) => {
    const val = event.target.value;
    if (val) {
      stop();
      seek(Number(val));
    }
  };
  for (const [id, direction] of [["replay-previous", -1], ["replay-next", 1]])
    find(id).onclick = () => {
      if (!index)
        return;
      stop();
      const events = index.events.map((e) => e.at);
      const next = direction > 0 ? events.find((t) => t > at + 1) : events.filter((t) => t < at - 1).at(-1);
      seek(next ?? (direction > 0 ? index.end : index.start));
    };
  find("replay-speed").onchange = (e) => {
    speed = Number(e.target.value);
  };
  async function tick() {
    if (!playing || !active || !index)
      return;
    const now = performance.now(), next = at + (now - lastReal) * speed;
    lastReal = now;
    await seek(next);
    if (at >= index.end)
      stop();
    if (playing)
      setTimeout(() => void tick(), 250);
  }
  play.onclick = () => {
    if (playing) {
      stop();
      return;
    }
    if (!index)
      return;
    if (at >= index.end)
      at = index.start;
    playing = true;
    lastReal = performance.now();
    play.textContent = "Ⅱ";
    play.setAttribute("aria-label", "Pause recording");
    tick();
  };
  return { active: () => active, at: () => at };
}

// web/sequence-command-state.ts
function sequenceCommandIdentity(sequence) {
  if (typeof sequence.sequenceId === "string" && typeof sequence.configurationRevision === "number" && Number.isInteger(sequence.configurationRevision) && sequence.configurationRevision > 0)
    return JSON.stringify([sequence.sequenceId, sequence.configurationRevision]);
  const runtime = new Set(["remainingSeconds", "completedIterations", "progressExposureCount", "exposureCount", "iterations"]);
  return JSON.stringify((Array.isArray(sequence.nodes) ? sequence.nodes : []).map((n) => ({ id: n.id, parentId: n.parentId, type: n.type, kind: n.kind, name: n.name, enabled: n.enabled ?? (n.state === "disabled" ? false : undefined), editableFields: n.editableFields, details: Object.fromEntries(Object.entries(n.details ?? {}).filter(([key]) => !runtime.has(key))) })));
}
function sequenceStopState(running, ownedStart, externalStop) {
  if (running !== true && !ownedStart)
    return running === false ? "Sequence is stopped." : "Waiting for N.I.N.A. acquisition state.";
  return externalStop || ownedStart ? "" : "Update the plugin to stop sequences started in N.I.N.A.";
}

// web/sequence-clock.ts
function sequenceCountdown(deadline, now = Date.now(), live = true) {
  if (!live)
    return "Remaining time unavailable · offline";
  if (!Number.isFinite(deadline))
    return "Remaining time unavailable";
  const seconds = Math.max(0, Math.ceil((deadline - now) / 1000));
  if (!seconds)
    return "Time reached";
  const h = Math.floor(seconds / 3600), m = Math.floor(seconds % 3600 / 60), s = seconds % 60;
  return "Remaining " + [h, m, s].map((v) => String(v).padStart(2, "0")).join(":");
}
function countdownElement(remaining, observedAt) {
  if (typeof remaining !== "number" || !Number.isFinite(remaining) || typeof observedAt !== "string")
    return;
  const deadline = Date.parse(observedAt) + remaining * 1000;
  if (!Number.isFinite(deadline))
    return;
  const span = document.createElement("span");
  span.className = "sequence-countdown";
  span.dataset.deadline = String(deadline);
  span.textContent = sequenceCountdown(deadline);
  return span;
}
function updateSequenceClocks(live, now = Date.now()) {
  for (const span of document.querySelectorAll(".sequence-countdown")) {
    const text = sequenceCountdown(Number(span.dataset.deadline), now, live);
    if (span.textContent !== text)
      span.textContent = text;
  }
}
function rolloverDeadline(details, observedAt, zone) {
  const { hours, minutes, seconds, rolloverTime } = details;
  if (![hours, minutes, seconds].every((v) => typeof v === "number" && Number.isInteger(v)) || Number(hours) < 0 || Number(hours) > 23 || Number(minutes) < 0 || Number(minutes) > 59 || Number(seconds) < 0 || Number(seconds) > 59 || typeof rolloverTime !== "string")
    return NaN;
  const match = /^(\d{2}):(\d{2}):(\d{2})$/.exec(rolloverTime);
  if (!match)
    return NaN;
  const rollover = +match[1] * 3600 + +match[2] * 60 + +match[3], target = Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds), observed = Date.parse(observedAt);
  if (!Number.isFinite(observed) || rollover >= 86400)
    return NaN;
  try {
    const format = new Intl.DateTimeFormat("en-CA", { timeZone: zone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" });
    const parts = (time) => Object.fromEntries(format.formatToParts(time).map((p) => [p.type, p.value]));
    const now = parts(observed), clock = +now.hour * 3600 + +now.minute * 60 + +now.second;
    const dayShift = clock < rollover && target >= rollover ? -1 : clock >= rollover && target < rollover ? 1 : 0;
    const wall = Date.UTC(+now.year, +now.month - 1, +now.day + dayShift, Number(hours), Number(minutes), Number(seconds));
    let result = wall;
    for (let i = 0;i < 3; i++) {
      const p = parts(result);
      result += wall - Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
    }
    return result;
  } catch {
    return NaN;
  }
}
function timedCountdownElement(details, observedAt, zone) {
  if (typeof details.remainingSeconds === "number")
    return countdownElement(details.remainingSeconds, observedAt);
  if (typeof observedAt !== "string" || typeof zone !== "string")
    return;
  const deadline = rolloverDeadline(details, observedAt, zone);
  return countdownElement((deadline - Date.parse(observedAt)) / 1000, observedAt);
}

// web/sequence-library.ts
function mountSequenceLibrary(api) {
  const saveButton = document.createElement("button"), saveAsButton = document.createElement("button");
  saveButton.textContent = "Save";
  saveAsButton.textContent = "Save As";
  document.getElementById("sequence-start").before(saveButton, saveAsButton);
  const saveDialog = document.createElement("dialog");
  saveDialog.className = "sequence-editor step-settings";
  saveDialog.setAttribute("aria-label", "Save sequence to NUC");
  saveDialog.innerHTML = '<h2>Save to NUC</h2><p>Targets</p><label>Name <input aria-label="Sequence filename" maxlength="95"></label><label><input type="checkbox" aria-label="Replace existing sequence"> Replace existing file</label><p role="status"></p><footer class="parameter-footer"><button data-cancel>Cancel</button><button data-save>Save</button></footer>';
  document.body.append(saveDialog);
  const nameInput = saveDialog.querySelector("input"), replaceInput = saveDialog.querySelector("[type=checkbox]"), saveMessage = saveDialog.querySelector("[role=status]"), saveConfirm = saveDialog.querySelector("[data-save]");
  let saveTokens = {}, saveReceipt;
  const openSave = (as) => {
    const sequence = api.states().sequence?.value ?? {};
    saveTokens = { sequenceId: sequence.sequenceId, expectedRevision: sequence.configurationRevision };
    nameInput.value = as ? "" : String(api.states().administration?.value.sequenceFileName ?? "");
    replaceInput.checked = !as;
    saveReceipt = undefined;
    saveMessage.textContent = "";
    saveConfirm.disabled = false;
    saveDialog.showModal();
    nameInput.focus();
  };
  saveButton.onclick = () => openSave(false);
  saveAsButton.onclick = () => openSave(true);
  saveDialog.querySelector("[data-cancel]").addEventListener("click", () => saveDialog.close());
  saveConfirm.onclick = () => {
    let fileName = nameInput.value.trim();
    if (!fileName)
      return;
    if (!fileName.toLowerCase().endsWith(".json"))
      fileName += ".json";
    saveConfirm.disabled = true;
    saveMessage.textContent = "Saving…";
    api.save({ ...saveTokens, fileName, replace: replaceInput.checked }).then((id) => {
      saveReceipt = id;
      saveMessage.textContent = id ? "Waiting for save receipt…" : "Save not confirmed. Check Operations.";
    }).catch((error) => {
      saveConfirm.disabled = false;
      saveMessage.textContent = String(error);
    });
  };
  const trigger = document.createElement("button");
  trigger.id = "sequence-load";
  trigger.type = "button";
  trigger.textContent = "↥ Load";
  document.getElementById("sequence-start").before(trigger);
  const style = document.createElement("style");
  style.textContent = `.sequence-actions{flex-wrap:wrap}@media(max-width:600px){.sequence-panel{min-width:0;width:100%;box-sizing:border-box}.sequence-header,.sequence-title{flex-wrap:wrap}.sequence-message{overflow-wrap:anywhere}}#sequence-load-dialog{width:min(540px,calc(100vw - 32px));box-sizing:border-box}#sequence-load-dialog header{display:flex;align-items:center;justify-content:space-between}#sequence-load-dialog h2{margin:0}#sequence-load-dialog input,#sequence-load-dialog select{width:100%;box-sizing:border-box;margin:10px 0}#sequence-load-dialog select{min-height:260px;padding:6px;background:#0c1c29;color:#dce8f2}#sequence-load-dialog option{padding:7px}#sequence-load-dialog footer{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}#sequence-load-dialog [role=status]{color:#9eafbd;font-size:12px}`;
  document.head.append(style);
  const dialog = document.createElement("dialog");
  dialog.id = "sequence-load-dialog";
  dialog.className = "parameter-dialog";
  dialog.setAttribute("aria-labelledby", "sequence-load-title");
  dialog.innerHTML = '<header><h2 id="sequence-load-title">Load from NUC</h2><button type="button" data-close aria-label="Close sequence picker">×</button></header><input type="search" aria-label="Find a sequence" placeholder="Find a sequence…"><select size="10" aria-label="Sequence JSON file"></select><p role="status"></p><p style="font-size:12px;color:#9eafbd">Replaces the loaded sequence. Does not start imaging.</p><footer><button type="button" data-refresh>Refresh files</button><button type="button" data-load>Load sequence</button></footer>';
  document.body.append(dialog);
  const query = dialog.querySelector("input"), list = dialog.querySelector("select"), message = dialog.querySelector("[role=status]"), load = dialog.querySelector("[data-load]"), refresh = dialog.querySelector("[data-refresh]");
  let identity = "", fingerprint = "";
  const context = () => api.session() + ":" + String(api.states().administration?.value.profile?.id ?? "") + ":" + String(api.states().sequence?.value.sequenceId ?? "");
  const files = () => (api.states().administration?.value.sequences ?? []).filter((f) => typeof f === "string");
  function update() {
    const saveReason = api.reason("sequence", "save");
    saveAsButton.disabled = !!saveReason;
    saveButton.disabled = !!saveReason || !api.states().administration?.value.sequenceFileName;
    saveAsButton.title = saveReason;
    saveButton.title = saveReason || "Save the loaded sequence to its Targets file";
    if (saveDialog.open && saveReceipt) {
      const op = (api.states().operations?.value.items ?? []).find((o) => o.requestId === saveReceipt);
      if (op?.completedAt) {
        saveReceipt = undefined;
        if (op.status === "succeeded")
          saveDialog.close();
        else {
          saveConfirm.disabled = false;
          saveMessage.textContent = op.error ?? "Save failed; name retained.";
        }
      }
    }
    const reason = api.reason("sequence", "load");
    trigger.disabled = !!reason;
    trigger.title = reason || "Choose a saved JSON sequence on the NUC";
    if (!dialog.open)
      return;
    const stale = context() !== identity, items = files(), key = JSON.stringify([items, query.value]);
    if (key !== fingerprint) {
      fingerprint = key;
      const previous = list.value;
      list.replaceChildren();
      for (const [prefix, label] of [["Targets/", "Targets"], ["", "Sequences"]]) {
        const group = document.createElement("optgroup");
        group.label = label;
        for (const name of items.filter((f) => (prefix ? f.startsWith(prefix) : !f.startsWith("Targets/")) && f.toLowerCase().includes(query.value.toLowerCase()))) {
          const option = document.createElement("option");
          option.value = name;
          option.textContent = prefix ? name.slice(prefix.length) : name;
          group.append(option);
        }
        if (group.children.length)
          list.append(group);
      }
      if (items.includes(previous))
        list.value = previous;
    }
    load.disabled = !!reason || stale || !list.value;
    refresh.disabled = !!api.reason("application", "refresh") || stale;
    message.textContent = stale ? "The profile or sequence changed. Reopen this picker." : reason || (!items.length ? "No JSON sequences found in the configured folders." : `${items.length} files on NUC${api.states().administration?.value.sequencesTruncated ? " · some files omitted by library limits" : ""}`);
  }
  trigger.onclick = () => {
    identity = context();
    fingerprint = "";
    query.value = "";
    dialog.showModal();
    update();
    query.focus();
  };
  dialog.querySelector("[data-close]").addEventListener("click", () => dialog.close());
  query.oninput = update;
  list.onchange = update;
  refresh.onclick = () => {
    if (!refresh.disabled)
      api.run("application", "refresh", {});
  };
  load.onclick = () => {
    update();
    if (load.disabled)
      return;
    const fileName = list.value;
    dialog.close();
    api.run("sequence", "load", { fileName });
  };
  return update;
}

