      const box = slider("Target temperature", -30, 10, s.connected === true && numeric2(s.temperatureSetPoint) ? Math.max(-30, Math.min(10, s.temperatureSetPoint)) : -10, "°C", "❄ Cool", "cool", "temperature");
      box.append(button("☀ Warm", "warm", { rampSeconds: 60 }, "warm"));
      const capture = document.createElement("section");
      capture.className = "capture-controls";
      capture.innerHTML = '<h3>Single capture</h3><label>Exposure <input aria-label="Exposure seconds" type="number" min="0.001" max="3600" step="any" value="3"> s</label><label class="save-choice"><input type="checkbox" aria-label="Save captured image"> Save</label>';
      const b = button("◉ Capture", "capture");
