var updateSequenceLibrary = mountSequenceLibrary({ states: () => current?.snapshot?.states ?? {}, session: () => current?.snapshot?.sessionId ?? "", reason: commandReason, run: control, save: (parameters) => send("sequence", "save", undefined, parameters, true) });
var updateSequenceEditor = mountSequenceEditor({
  states: () => current?.snapshot?.states ?? {},
  session: () => current?.snapshot?.sessionId ?? "",
  live: () => !preview && fresh(),
  reason: commandReason,
  run: (device, action, parameters) => {
    send(device, action, undefined, parameters);
  },
  schema: (type) => request("/api/v1/sequence/insertion-schema?type=" + encodeURIComponent(type)),
  submit: (parameters) => send("sequence", "insertDraft", undefined, parameters, true)
});
function updateClock() {
  write("local-clock", clockFormat.format(new Date(replayMode && replayFrame ? replayFrame.at : Date.now())));
  const observed = current?.snapshot?.states.camera?.observedAt;
  const age = observed ? (Date.now() - Date.parse(observed)) / 1000 : NaN;
  write("observation-age", preview ? "Illustrative data" : !Number.isFinite(age) ? "Waiting for telemetry" : age < -5 ? "Device clock differs" : `Observed ${Math.max(0, Math.floor(age))}s ago${fresh() ? "" : " · stale"}`);
  if (!preview) {
    write("connection", fresh() ? "Live" : socketReady && current?.bridge.connected ? "Stale" : "Offline");
    el3("connection").classList.toggle("offline", !fresh());
    document.body.dataset.transport = fresh() ? "live" : "offline";
  }
  if (replayMode) {
    write("connection", "REPLAY");
    el3("connection").classList.remove("offline");
    document.body.dataset.transport = "replay";
    write("observation-age", replayFrame?.gap ? "No recorded telemetry" : "Recorded · " + (replayFrame ? time(new Date(replayFrame.lastTelemetryAt).toISOString()) : "Loading"));
  }
  const readingsAvailable = replayMode ? !!replayFrame && !replayFrame.gap : preview || fresh();
  renderRoofStatus(current?.snapshot?.states ?? {}, readingsAvailable);
  const roof = el3("roof-status");
  roof.disabled = true;
  roof.onclick = null;
  roof.title = String(topic("safetyConnection").error ?? "Roof monitoring stays connected");
  if (topic("safetyConnection").error && topic("safety").connected !== true)
    roof.textContent = "Roof · retrying";
  updateExposureClock(readingsAvailable, replayMode ? replayFrame?.at : undefined);
  updateSequenceClocks(readingsAvailable, replayMode ? replayFrame?.at : undefined);
  renderActions();
  updateDevicePanels();
  updateSequenceEditor();
  updateSequenceLibrary();
}
setInterval(updateClock, 250);
document.addEventListener("visibilitychange", updateClock);
function render() {
  const states = current?.snapshot?.states ?? {}, live = replayMode ? !!replayFrame && !replayFrame.gap : preview || fresh();
  renderDashboard(states, live, current?.snapshot?.sessionId ?? "", replayMode ? replayFrame?.at : undefined);
  const empty = el3("image-empty");
  empty.querySelector("strong").textContent = replayMode ? "No recorded image" : "Waiting for an image";
  empty.querySelector("span").textContent = replayMode ? "No image preview was recorded at this time." : "The next image preview will appear here.";
  el3("latest-preview").alt = replayMode ? "Recorded image preview" : "Latest image from N.I.N.A.";
  const app = topic("application"), diagnostic = topic("diagnostics");
  write("environment", preview ? "Illustrative preview" : app.environment === "simulation" ? "Simulation" : app.environment === "equipment" ? "Equipment" : "Environment unknown");
  write("api-version", "Starfront Control");
  for (const [id, key] of [
    ["memory", "processPrivateBytes"],
    ["heap", "managedLiveEstimateBytes"],
    ["logs", "ownLogBytes"]
  ])
    write(id, numeric2(diagnostic[key]) ? format(diagnostic[key] / 1e6, 1, " MB") : "—");
  write("queued", diagnostic.pendingTopics);
  write("clients", diagnostic.clients);
  write("diagnostic-memory", numeric2(diagnostic.processPrivateBytes) ? format(diagnostic.processPrivateBytes / 1e6, 1, " MB") : "—");
  write("diagnostic-heap", numeric2(diagnostic.managedLiveEstimateBytes) ? format(diagnostic.managedLiveEstimateBytes / 1e6, 1, " MB") : "—");
  if (typeof diagnostic.observedAt === "string" && diagnostic.observedAt !== lastMetric && numeric2(diagnostic.processPrivateBytes)) {
    lastMetric = diagnostic.observedAt;
    samples.push({ at: lastMetric, bytes: diagnostic.processPrivateBytes });
    if (samples.length > 720)
      samples.shift();
    renderPlot();
  }
  const body = el3("operations");
  body.replaceChildren();
  const ops = operations();
  for (const op of ops)
    if (op.completedAt && pending.get(op.device) === op.requestId) {
      pending.delete(op.device);
      pendingActions.delete(op.device);
    }
  if (!ops.length) {
    const cell = body.insertRow().insertCell();
    cell.colSpan = 4;
    cell.textContent = "No operations reported";
  }
  for (const op of ops.slice(0, 12)) {
    const row = body.insertRow();
    row.title = op.requestId + (op.error ? ` · ${op.error}` : "");
    for (const value of [time(op.acceptedAt), op.device, op.action, op.status])
      row.insertCell().textContent = value;
  }
  updateClock();
}
function renderPlot() {
  const plot2 = el3("memory-plot"), width = Math.max(350, plot2.clientWidth);
  plot2.setAttribute("viewBox", `0 0 ${width} 180`);
  el3("plot-empty").setAttribute("x", String(width / 2));
  el3("plot-empty").setAttribute("visibility", samples.length ? "hidden" : "visible");
  const max = Math.max(1e8, ...samples.map((x) => x.bytes)) * 1.15, grid = el3("plot-grid");
  grid.replaceChildren();
  for (let i = 0;i <= 4; i++) {
    const y = 160 - i * 38;
    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    for (const [key, value] of Object.entries({
      x1: "40",
      x2: String(width - 10),
      y1: String(y),
      y2: String(y)
    }))
      line.setAttribute(key, value);
    const label = document.createElementNS("http://www.w3.org/2000/svg", "text");
    label.setAttribute("x", "4");
    label.setAttribute("y", String(y + 4));
    label.textContent = String(Math.round(max * i / 4 / 1e6));
    grid.append(line, label);
  }
  const first = samples[0]?.at, last = samples.at(-1)?.at;
  write("plot-start", time(first));
  write("plot-end", time(last));
  el3("memory-line").setAttribute("d", samples.map((s, i) => `${i ? "L" : "M"}${40 + (Date.parse(s.at) - Date.parse(first)) / Math.max(1, Date.parse(last) - Date.parse(first)) * (width - 50)},${160 - s.bytes / max * 152}`).join(" "));
}
function connect() {
  const socket = new WebSocket(`${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}${gatewayBase}/socket`);
  websocket = socket;
  socket.onopen = () => {
    socketReady = true;
    retry = 1000;
  };
  socket.onmessage = (event) => {
    if (socket !== websocket)
      return;
    try {
      current = JSON.parse(String(event.data));
    } catch {
      notice("An invalid telemetry message was ignored.");
      return;
    }
    liveCurrent = current;
    if (replayMode) {
      current = replayFrame ? { bridge: { connected: false }, snapshot: replayFrame.snapshot } : null;
      return;
    }
    if (current.snapshot && current.snapshot.sessionId !== currentSession) {
      if (currentSession && pending.size)
        notice("N.I.N.A. restarted. Check Operations and equipment state before issuing another command.");
      pending.clear();
      pendingActions.clear();
      currentSession = current.snapshot.sessionId;
      samples.length = 0;
      lastMetric = "";
    }
    render();
  };
  socket.onclose = () => {
    if (socket !== websocket)
      return;
    socketReady = false;
    if (liveCurrent)
      liveCurrent.bridge.connected = false;
    if (!replayMode && current)
      current.bridge.connected = false;
    render();
    setTimeout(connect, retry);
    if (gatewayBase)
      request("/auth/dashboard-session", {}).catch(() => {});
    retry = Math.min(1e4, retry * 2);
  };
}
async function start() {
  try {
    if (preview) {
      current = await request("/preview.json");
      const now = new Date().toISOString();
      for (const state of Object.values(current.snapshot.states))
        state.observedAt = now;
      topic("camera").exposureEndTime = new Date(Date.now() + 117000).toISOString();
      topic("diagnostics").observedAt = now;
      write("connection", "Preview");
      el3("connection").classList.remove("offline");
      el3("preview-banner").hidden = false;
      el3("preview-link").hidden = true;
    } else {
      const ticket = new URLSearchParams(location.hash.slice(1)).get("session");
      if (ticket) {
        history.replaceState(null, "", location.pathname + location.search);
        await request("/auth/session", { ticket });
      }
      await request(gatewayBase ? "/auth/dashboard-session" : "/auth/local-session", {});
      current = await request("/api/v1/status");
    }
    liveCurrent = current;
    el3("notice").hidden = true;
    el3("monitor").hidden = false;
    render();
    if (!preview)
      connect();
  } catch {
    notice("Connecting to the local dashboard…");
    setTimeout(() => void start(), 5000);
  }
}
mountReplay({
  read: (path, signal) => request(path, undefined, signal),
  mode(active) {
    replayMode = active;
    replayFrame = null;
    current = active ? null : liveCurrent;
    samples.length = 0;
    lastMetric = "";
    confirm.close();
    document.querySelectorAll("dialog[open]").forEach((d) => d.close());
    render();
  },
  frame(frame) {
    if (replayFrame && frame.at < replayFrame.at) {
      samples.length = 0;
      lastMetric = "";
    }
    replayFrame = frame;
    current = { bridge: { connected: false }, snapshot: frame.snapshot };
    render();
  }
});
new ResizeObserver(renderPlot).observe(el3("memory-plot"));
start();
window.addEventListener("focus", () => {
  ensuredSafetyContext = "";
  renderActions();
});
